/* =====================================================================
   V26.72 · FINANZAS («VB Treasury & Cashflow») y CONTABILIDAD («VB Ledger & Tax»)
   ---------------------------------------------------------------------
   · Todo en centavos enteros. Sólo lee lo que el sistema ya registra (ventas, cobros, caja, compras, proveedores,
     mermas, traspasos, cierres, liquidaciones de sueldo); nunca cambia esas operaciones.
   · Finanzas: tablero (efectivo, bancos, a cobrar, a pagar, margen neto estimado), flujo de fondos proyectado por
     semana, compromisos, cobrar/pagar, rentabilidad por operación, conciliación asistida con extracto bancario,
     tablero de cobros digitales (la pasarela VB Pay queda preparada y APAGADA hasta tener cuenta y credenciales)
     y un copiloto de reglas locales (sin IA, sin costo).
   · Contabilidad: asientos de partida doble generados solos desde cada evento (id determinístico → no se duplican),
     cada asiento con su huella SHA-256 y cierre de período que encadena las huellas; Libro Diario, Mayor, Sumas y
     saldos, pre-liquidación de IVA y portal del contador (rol «contador», sólo lectura y exportación).
   · Es contabilidad de GESTIÓN: no reemplaza los libros legales, la DDJJ de IVA ni al contador [VERIFICAR].
   · Cliente: apagado hasta que el administrador lo active. Demos: encendido con datos «ejemplo».
   ===================================================================== */
const FIN_DAY=86400000;
IC.chart='M4 20V10M10 20V4M16 20v-7M22 20H2';IC.book='M4 4h7a3 3 0 0 1 3 3v13a2 2 0 0 0-2-2H4zM20 4h-6a3 3 0 0 0-3 3v13a2 2 0 0 1 2-2h7z';
const FIN_PCT_DEF=[
 ['1','ACTIVO',0],['1.1.01','Caja',1],['1.1.02','Bancos',1],['1.1.03','Tarjetas y billeteras a cobrar',1],['1.1.04','Deudores por ventas',1],['1.1.05','IVA Crédito Fiscal',1],['1.1.06','Mercaderías',1],
 ['2','PASIVO',0],['2.1.01','Proveedores',1],['2.1.02','IVA Débito Fiscal',1],['2.1.03','Sueldos a pagar',1],['2.1.04','Percepciones y retenciones a pagar',1],['2.1.05','Saldos a favor y gift cards de clientes',1],
 ['3','PATRIMONIO NETO',0],['3.1.01','Capital',1],['3.1.02','Resultados acumulados',1],
 ['4','RESULTADOS POSITIVOS',0],['4.1.01','Ventas minoristas',1],['4.1.02','Ventas mayoristas',1],['4.2.01','Otros ingresos',1],['4.2.02','Sobrantes de caja',1],
 ['5','RESULTADOS NEGATIVOS',0],['5.1.01','Costo de mercadería vendida',1],['5.2.01','Comisiones y gastos financieros',1],['5.2.02','Gastos generales',1],['5.2.03','Sueldos y jornales',1],['5.2.04','Mermas y roturas',1],['5.2.05','Faltantes de caja',1]];
const FIN_DIG=['debito','credito','transferencia','qr','modo','pedidosya'];
const FIN_PL_DEF={debito:1,credito:10,qr:0,modo:1,transferencia:0,pedidosya:7};
function finCfg(){const c=S.cfg.fin=S.cfg.fin||{};if(c.on===undefined)c.on=!IS_CLIENT;if(!c.plazos)c.plazos=Object.assign({},FIN_PL_DEF);if(!c.bancos)c.bancos=[];if(c.provPlazo===undefined)c.provPlazo=30;if(c.umbral===undefined)c.umbral=0;if(c.ivaDia===undefined)c.ivaDia=20;if(c.est===undefined)c.est=false;if(c.weeks===undefined)c.weeks=8;return c;}
function acCfg(){const c=S.cfg.acct=S.cfg.acct||{};if(c.on===undefined)c.on=!IS_CLIENT;if(!c.since)c.since=dkey(now()-(IS_CLIENT?0:60)*FIN_DAY).slice(0,8)+'01';if(!c.tax)c.tax=[];return c;}
const finOn=()=>!!finCfg().on,acOn=()=>!!acCfg().on;
function finInit(){['finCmp','finRec','journal','acClose','finIva'].forEach(k=>{if(!Array.isArray(S[k]))S[k]=[];});if(!Array.isArray(S.pcta)||!S.pcta.length)S.pcta=FIN_PCT_DEF.map(([c,n,i])=>({id:c,code:c,name:n,imp:!!i}));}
const acName=c=>{const a=(S.pcta||[]).find(x=>x.code===c);return a?a.name:c;};
const finNorm=t=>String(t||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
const finYM=ts=>dkey(ts).slice(0,7);
const fDmy=ts=>dmy(dkey(ts));
/* ---------- lectura de las operaciones ---------- */
function finPays(s){if(s.pays&&s.pays.length)return s.pays.map(p=>({m:p.m,a:+p.a||0,fee:+p.fee||0}));return [{m:s.method||'efectivo',a:+s.total||0,fee:+s.fee||0}];}
function finSaleCost(s){return (s.items||[]).reduce((a,i)=>a+Math.round((+i.cost||0)*(+i.qty||0)),0);}
function finSaleIva(s){return s.arca&&s.arca.estado==='aprobado'&&+s.arca.iva>0?+s.arca.iva:0;}
const finOk=s=>s.status==='ok';
/* acreditaciones digitales: cada cobro digital entra al banco a los N días configurados [VERIFICAR con el procesador] */
function finAccr(){const P=finCfg().plazos,out=[];S.sales.filter(finOk).forEach(s=>finPays(s).forEach((p,i)=>{if(!FIN_DIG.includes(p.m))return;const d=+P[p.m]||0;out.push({id:s.id+':'+i,sale:s,m:p.m,gross:p.a,fee:p.fee,net:p.a-p.fee,ts:s.ts,due:s.ts+d*FIN_DAY});}));return out;}
function finCustOpen(){/* deuda de clientes por venta (FIFO): lo cobrado cancela primero lo más viejo */const out=[];const by={};S.sales.filter(s=>finOk(s)&&saleFiadoAmt(s)>0).forEach(s=>{(by[s.cust]=by[s.cust]||[]).push(s);});
 Object.entries(by).forEach(([cid,L])=>{L.sort((a,b)=>a.ts-b.ts);let paid=S.fiadoPays.filter(p=>p.cust===cid).reduce((a,p)=>a+p.amount,0);L.forEach(s=>{const amt=saleFiadoAmt(s),u=Math.min(paid,amt);paid-=u;const r=amt-u;if(r>0){const c=S.customers.find(x=>x.id===cid);const due=s.due||(s.ts+((c&&+c.term)||30)*FIN_DAY);out.push({sale:s,cust:cid,name:c?((c.name||'')+' '+(c.last||'')).trim()||'Cliente':'Cliente',amt:r,due});}});});return out;}
function finProvOpen(){const P=finCfg().provPlazo,out=[];(S.suppliers||[]).forEach(pv=>{const L=(S.supLedger||[]).filter(e=>e.provId===pv.id).sort((a,b)=>(a.seq||0)-(b.seq||0));const saldo=L.length?+L[L.length-1].saldo||0:0;if(saldo<=0)return;
 let rest=saldo;const R=(S.receipts||[]).filter(r=>r.provId===pv.id&&r.cond!=='contado').sort((a,b)=>b.ts-a.ts);R.forEach(r=>{if(rest<=0)return;const a=Math.min(rest,+r.total||0);rest-=a;const f=r.fecha?Date.parse(r.fecha+'T12:00:00'):r.ts;out.push({prov:pv,amt:a,due:f+((+pv.plazo)||P)*FIN_DAY,ref:(r.tipo||'')+' '+(r.nro||'')});});
 if(rest>0)out.push({prov:pv,amt:rest,due:now(),ref:'saldo anterior'});});return out;}
function finCash(){let t=0;S.sessions.filter(s=>!s.closedAt).forEach(s=>{try{t+=arqueoCalc(s,arqInputs(s)).expectedCash||0;}catch(e){}});return t;}
function finBank(){const c=finCfg();if(!c.bancos.length)return{t:0,est:false};let t=0;c.bancos.forEach(b=>t+=+b.saldo||0);const since=Math.min(...c.bancos.map(b=>Date.parse((b.fecha||dkey(now()))+'T00:00:00')));
 t+=finAccr().filter(a=>a.due>=since&&a.due<=now()).reduce((x,a)=>x+a.net,0);t-=(S.supLedger||[]).filter(e=>e.tipo==='Pago'&&e.ts>=since&&e.medio&&e.medio!=='efectivo').reduce((x,e)=>x+(+e.monto||0),0);return{t,est:true};}
/* compromisos: alquiler, servicios, impuestos, sueldos… se repiten según la frecuencia */
function finOcc(c,from,to){const out=[];let d=Date.parse((c.next||dkey(now()))+'T12:00:00');const step={semanal:7,quincenal:15,mensual:0,unico:-1}[c.freq||'mensual'];let n=0;
 while(d<=to&&n<200){if(d>=from)out.push(d);if(step===-1)break;if(step===0){const x=new Date(d);x.setMonth(x.getMonth()+1);d=x.getTime();}else d+=step*FIN_DAY;n++;}return out;}
function finIvaMonth(ym){const J=acOn()?S.journal.filter(a=>a.f.slice(0,7)===ym):null;if(J){let df=0,cf=0;J.forEach(a=>a.l.forEach(l=>{if(l.c==='2.1.02')df+=(l.h||0)-(l.d||0);if(l.c==='1.1.05')cf+=(l.d||0)-(l.h||0);}));return{df,cf};}
 const df=S.sales.filter(s=>finOk(s)&&finYM(s.ts)===ym).reduce((a,s)=>a+finSaleIva(s),0);return{df,cf:0};}
function finFlow(weeks){const c=finCfg(),t0=new Date(dkey(now())+'T00:00:00').getTime(),N=weeks||c.weeks,end=t0+N*7*FIN_DAY;
 const W=[...Array(N)].map((_,i)=>({from:t0+i*7*FIN_DAY,to:t0+(i+1)*7*FIN_DAY-1,inn:0,out:0,det:[]}));const wk=ts=>Math.max(0,Math.min(N-1,Math.floor((ts-t0)/(7*FIN_DAY))));
 const add=(ts,amt,kind,txt)=>{if(ts>end||!amt)return;const w=W[wk(ts)];if(kind==='in')w.inn+=amt;else w.out+=amt;w.det.push({kind,amt,txt,late:ts<t0});};
 finAccr().filter(a=>a.due>=t0).forEach(a=>add(a.due,a.net,'in','Acreditación '+(MET[a.m]||a.m)+' venta '+a.sale.n));
 finCustOpen().forEach(o=>add(Math.max(o.due,t0),o.amt,'in','Cuenta corriente: '+o.name+(o.due<t0?' (vencida)':'')));
 if(c.est){const d28=S.sales.filter(s=>finOk(s)&&s.ts>now()-28*FIN_DAY);const per=Math.round(d28.reduce((a,s)=>a+finPays(s).filter(p=>p.m==='efectivo').reduce((x,p)=>x+p.a,0),0)/28*7);W.forEach(w=>{if(per>0){w.inn+=per;w.det.push({kind:'in',amt:per,txt:'Ventas en efectivo estimadas (promedio de 28 días)',est:1});}});}
 (S.finCmp||[]).filter(x=>x.on!==false).forEach(x=>finOcc(x,t0,end).forEach(d=>add(d,+x.amount||0,'out',x.name)));
 finProvOpen().forEach(o=>add(Math.max(o.due,t0),o.amt,'out','Proveedor '+(o.prov.name||o.prov.razon||'')+' '+o.ref+(o.due<t0?' (vencido)':'')));
 const ym=finYM(now()),iv=finIvaMonth(ym),net=iv.df-iv.cf;if(net>0){const x=new Date(t0);x.setMonth(x.getMonth()+1);x.setDate(c.ivaDia);add(x.getTime(),net,'out','IVA estimado de '+ym+' [VERIFICAR]');}
 let bal=finCash()+finBank().t;const start=bal;W.forEach(w=>{bal+=w.inn-w.out;w.bal=bal;});return{W,start,t0};}
function finAlerts(F){const c=finCfg(),A=[];(F||finFlow()).W.forEach(w=>{if(w.bal<c.umbral){const acc=w.det.filter(d=>d.kind==='in'&&/Acreditaci/.test(d.txt)).reduce((a,d)=>a+d.amt,0);A.push({c:'red',t:'Bache de caja previsto la semana del '+fDmy(w.from)+': el saldo proyectado queda en '+money(w.bal)+(c.umbral?' (tu mínimo es '+money(c.umbral)+')':'')+'. Egresos '+money(w.out)+' contra ingresos '+money(w.inn)+(acc?'; '+money(acc)+' son acreditaciones de tarjetas o billeteras que llegan esa semana':'')+'.'});}});
 const venc=finCustOpen().filter(o=>o.due<now());if(venc.length)A.push({c:'amb',t:venc.length+' cuenta(s) corriente(s) vencida(s) por '+money(venc.reduce((a,o)=>a+o.amt,0))+'.'});
 const pv=finProvOpen().filter(o=>o.due<now());if(pv.length)A.push({c:'amb',t:'Deuda vencida con proveedores: '+money(pv.reduce((a,o)=>a+o.amt,0))+'.'});return A;}
function finProfit(from,to){const S0=S.sales.filter(s=>finOk(s)&&s.ts>=from&&s.ts<=to);let v=0,cost=0,fee=0,iva=0;S0.forEach(s=>{v+=+s.total||0;cost+=finSaleCost(s);fee+=finPays(s).reduce((a,p)=>a+p.fee,0);iva+=finSaleIva(s);});
 const gastos=S.movs.filter(m=>m.type==='egreso'&&m.ts>=from&&m.ts<=to&&!m.ref).reduce((a,m)=>a+(+m.amount||0),0);const sue=(S.hrPays||[]).filter(p=>p.ts>=from&&p.ts<=to).reduce((a,p)=>a+(+p.total||0),0);
 const mer=(typeof mermasL==='function'?mermasL():S.mermas||[]).filter(m=>m.ts>=from&&m.ts<=to).reduce((a,m)=>a+(+m.value||0),0);
 return{n:S0.length,v,cost,fee,iva,gastos,sue,mer,net:v-cost-fee-iva-gastos-sue-mer,gross:v-cost-fee-iva};}
/* ---------- copiloto de reglas (sin IA) ---------- */
function finAsk(q){const t=finNorm(q).trim();if(!t)return 'Escribí una pregunta, por ejemplo: «cuánta plata voy a tener en 15 días».';const F=finFlow(12);
 let m=t.match(/(\d+)\s*(dia|dias|semana|semanas)/);if(/liquidez|plata|saldo|voy a tener|tendre|cuanto hay/.test(t)){let d=m?(+m[1])*(/semana/.test(m[2])?7:1):7;d=Math.min(d,84);const w=F.W[Math.min(F.W.length-1,Math.max(0,Math.ceil(d/7)-1))];return 'Saldo proyectado a '+d+' día(s) (semana del '+fDmy(w.from)+'): '+money(w.bal)+'. Hoy: '+money(F.start)+' entre cajas abiertas y bancos informados. Ingresos esperados hasta entonces '+money(F.W.slice(0,F.W.indexOf(w)+1).reduce((a,x)=>a+x.inn,0))+', egresos comprometidos '+money(F.W.slice(0,F.W.indexOf(w)+1).reduce((a,x)=>a+x.out,0))+'.';}
 if(/cobrar|me deben|deuda de clientes|clientes deben/.test(t)){const o=finCustOpen(),a=finAccr().filter(x=>x.due>now());return 'A cobrar: '+money(o.reduce((x,y)=>x+y.amt,0))+' de cuentas corrientes ('+o.filter(x=>x.due<now()).length+' vencidas) y '+money(a.reduce((x,y)=>x+y.net,0))+' de tarjetas y billeteras por acreditar.';}
 if(/pagar|debo|proveedor/.test(t)){const o=finProvOpen();return 'A pagar a proveedores: '+money(o.reduce((x,y)=>x+y.amt,0))+(o.filter(x=>x.due<now()).length?' (hay deuda vencida)':'')+'. Compromisos de los próximos 30 días: '+money((S.finCmp||[]).reduce((a,c)=>a+finOcc(c,now(),now()+30*FIN_DAY).length*(+c.amount||0),0))+'.';}
 if(/bache|riesgo|peor|alerta|falta plata/.test(t)){const A=finAlerts(F).filter(a=>a.c==='red');if(!A.length){const w=F.W.reduce((a,b)=>b.bal<a.bal?b:a);return 'No hay baches previstos en 12 semanas. La semana más ajustada es la del '+fDmy(w.from)+' con '+money(w.bal)+'.';}return A[0].t;}
 if(/margen|ganancia|rentab/.test(t)){const p=finProfit(now()-30*FIN_DAY,now());return 'Últimos 30 días: ventas '+money(p.v)+', margen neto estimado '+money(p.net)+(p.v?' ('+(p.net/p.v*100).toFixed(1).replace('.',',')+' %)':'')+'. Resta costo '+money(p.cost)+', comisiones '+money(p.fee)+', IVA '+money(p.iva)+', gastos '+money(p.gastos)+', sueldos '+money(p.sue)+' y mermas '+money(p.mer)+'.';}
 if(/desvio|presupuesto/.test(t)){const L=(S.finCmp||[]).filter(c=>+c.budget>0);if(!L.length)return 'Cargá un presupuesto mensual en algún compromiso para medir desvíos.';const ym=finYM(now());return L.map(c=>{const real=S.movs.filter(m=>m.type==='egreso'&&finYM(m.ts)===ym&&finNorm(m.concept||'').includes(finNorm(c.name).split(' ')[0])).reduce((a,m)=>a+(+m.amount||0),0);return c.name+': presupuesto '+money(+c.budget)+', real '+money(real)+(real>+c.budget?' (se pasó '+money(real-c.budget)+')':'');}).join('\n');}
 return 'Todavía no entiendo esa pregunta. Probá con: «liquidez en 15 días», «cuánto me deben», «cuánto debo», «hay algún bache», «margen del mes» o «desvío del presupuesto».';}
/* ---------- CONTABILIDAD: asientos automáticos ---------- */
const acLine=(c,d,h)=>({c,d:Math.round(d)||0,h:Math.round(h)||0});
function acHash(a){return sha256(JSON.stringify({id:a.id,f:a.f,src:a.src,ley:a.ley,l:a.l.map(x=>[x.c,x.d,x.h])}));}
function acPayAcc(m){return m==='efectivo'?'1.1.01':m==='transferencia'?'1.1.02':(m==='fiado'||m==='cc')?'1.1.04':(m==='monedero'||m==='giftcard')?'2.1.05':'1.1.03';}
function acClosedYM(){return (S.acClose||[]).reduce((a,c)=>c.id>a?c.id:a,'');}
function acEvents(){const ev=[],since=Date.parse(acCfg().since+'T00:00:00');const ok=ts=>ts>=since;
 S.sales.forEach(s=>{if(!ok(s.ts)||s.status==='pendiente'||s.status==='suspendido')return;if(s.status!=='ok'&&s.status!=='anulada')return;
  const L=[];finPays(s).forEach(p=>{if(p.a)L.push(acLine(acPayAcc(p.m),p.a,0));if(p.fee){L.push(acLine('5.2.01',p.fee,0));L.push(acLine(acPayAcc(p.m),0,p.fee));}});
  const iva=finSaleIva(s),vta=s.wch==='mayorista'?'4.1.02':'4.1.01';const tot=finPays(s).reduce((a,p)=>a+p.a,0);L.push(acLine(vta,0,tot-iva));if(iva)L.push(acLine('2.1.02',0,iva));
  const cmv=finSaleCost(s);if(cmv>0){L.push(acLine('5.1.01',cmv,0));L.push(acLine('1.1.06',0,cmv));}
  ev.push({id:'AS-v-'+s.id,ts:s.ts,src:{t:'venta',id:s.id},ley:'Venta '+s.n+(iva?' · factura '+(s.arca.letra||'')+' '+(s.arca.pto||'')+'-'+(s.arca.nro||''):'')+(s.wch==='mayorista'?' · mayorista':''),l:L});
  if(s.status==='anulada')ev.push({id:'AS-vx-'+s.id,ts:s.voidTs||s.voidedAt||now(),src:{t:'anulación',id:s.id},ley:'Anulación de la venta '+s.n+(s.arcaNC?' (nota de crédito)':''),l:L.map(x=>acLine(x.c,x.h,x.d)),rev:'AS-v-'+s.id});});
 (S.fiadoPays||[]).forEach(p=>{if(!ok(p.ts))return;const c=S.customers.find(x=>x.id===p.cust);ev.push({id:'AS-c-'+p.id,ts:p.ts,src:{t:'cobro',id:p.id},ley:'Cobro de cuenta corriente'+(c?' · '+(c.name||''):''),l:[acLine(acPayAcc(p.method||'efectivo'),p.amount,0),acLine('1.1.04',0,p.amount)]});});
 const cmpMov=new Set([...(S.receipts||[]).map(r=>r.movId),...(S.supLedger||[]).map(e=>e.movId)].filter(Boolean));
 S.movs.forEach(m=>{if(!ok(m.ts)||!(+m.amount>0)||cmpMov.has(m.id))return;if(m.type==='ingreso'&&!m.saleId)ev.push({id:'AS-m-'+m.id,ts:m.ts,src:{t:'ingreso',id:m.id},ley:'Ingreso de caja · '+(m.concept||rubName(m.rubro)||''),l:[acLine('1.1.01',m.amount,0),acLine('4.2.01',0,m.amount)]});
  else if(m.type==='egreso')ev.push({id:'AS-m-'+m.id,ts:m.ts,src:{t:'egreso',id:m.id},ley:'Egreso de caja · '+(m.concept||'')+(m.rubro?' · '+rubName(m.rubro):''),l:[acLine(/sueldo/i.test(m.concept||'')?'5.2.03':'5.2.02',m.amount,0),acLine('1.1.01',0,m.amount)]});});
 (S.receipts||[]).forEach(r=>{if(!ok(r.ts))return;const iv=(S.finIva||[]).find(x=>x.id===r.id);const iva=iv?+iv.iva||0:0;const L=[acLine('1.1.06',(+r.total||0)-iva,0)];if(iva)L.push(acLine('1.1.05',iva,0));L.push(acLine('2.1.01',0,+r.total||0));
  ev.push({id:'AS-r-'+r.id,ts:r.ts,src:{t:'compra',id:r.id},ley:'Ingreso de mercadería · '+(r.tipo||'')+' '+(r.nro||''),l:L});});
 (S.supLedger||[]).forEach(e=>{if(!ok(e.ts)||!(+e.monto>0))return;if(e.tipo==='Pago')ev.push({id:'AS-p-'+e.id,ts:e.ts,src:{t:'pago a proveedor',id:e.id},ley:'Pago a proveedor'+(e.medio?' · '+e.medio:''),l:[acLine('2.1.01',e.monto,0),acLine(e.medio&&e.medio!=='efectivo'?'1.1.02':'1.1.01',0,e.monto)]});
  else if(e.tipo==='Nota de Crédito')ev.push({id:'AS-pn-'+e.id,ts:e.ts,src:{t:'nota de crédito de proveedor',id:e.id},ley:'Nota de crédito de proveedor',l:[acLine('2.1.01',e.monto,0),acLine('1.1.06',0,e.monto)]});});
 (typeof mermasL==='function'?mermasL():S.mermas||[]).forEach(m=>{if(!ok(m.ts)||!(+m.value>0)||m.origin==='ejemplo-x')return;ev.push({id:'AS-x-'+m.id,ts:m.ts,src:{t:'merma',id:m.id},ley:'Merma · '+(m.tipo||'')+' · '+(m.name||''),l:[acLine('5.2.04',m.value,0),acLine('1.1.06',0,m.value)]});});
 (S.transfers||[]).forEach(x=>{if(!ok(x.ts)||!(+x.amount>0)||x.rev)return;ev.push({id:'AS-t-'+x.id,ts:x.ts,src:{t:'traspaso',id:x.id},ley:'Traspaso entre cajas'+(x.n?' '+x.n:''),l:[acLine('1.1.01',x.amount,0),acLine('1.1.01',0,x.amount)]});});
 (S.closures||[]).forEach(c=>{const d=c.data&&+c.data.diff;if(!ok(c.ts)||!d)return;ev.push({id:'AS-z-'+c.id,ts:c.ts,src:{t:'cierre',id:c.id},ley:'Diferencia del cierre de caja '+(c.zn||''),l:d>0?[acLine('1.1.01',d,0),acLine('4.2.02',0,d)]:[acLine('5.2.05',-d,0),acLine('1.1.01',0,-d)]});});
 (S.hrPays||[]).forEach(p=>{if(!ok(p.ts)||!(+p.total>0))return;ev.push({id:'AS-s-'+p.id,ts:p.ts,src:{t:'liquidación de sueldos',id:p.id},ley:'Liquidación interna de sueldos '+(p.period||''),l:[acLine('5.2.03',p.total,0),acLine('2.1.03',0,p.total)]});});
 return ev;}
/* sólo genera asientos quien puede escribirlos (administrador o «Contabilidad: administrar»); el contador ve lo ya contabilizado */
function acPost(){if(!acOn())return 0;finInit();if(!(isAdm()||can('accounting_admin')))return 0;const have=new Set(S.journal.map(a=>a.id)),cl=acClosedYM();let n=0;window.__acErr=[];
 acEvents().forEach(e=>{if(have.has(e.id))return;if(e.rev&&!have.has(e.rev))return;const l=e.l.filter(x=>x.d||x.h);const D=l.reduce((a,x)=>a+x.d,0),H=l.reduce((a,x)=>a+x.h,0);
  if(!l.length||D!==H){window.__acErr.push(e.ley+' (no balancea: '+money(D)+' / '+money(H)+')');return;}
  let f=dkey(e.ts),ley=e.ley;if(cl&&f.slice(0,7)<=cl){ley+=' (evento de '+f+', período cerrado)';f=dkey(now());}
  const a={id:e.id,f,ts:now(),src:e.src,ley,l,by:user?user.name:'sistema'};a.h=acHash(a);S.journal.push(a);have.add(e.id);n++;});
 if(n){audit('CONTABILIDAD',n+' asiento(s) generado(s) automáticamente');save();}return n;}
function acVerify(){let bad=0;(S.journal||[]).forEach(a=>{if(a.h!==acHash(a))bad++;});let prev='GENESIS',badC=0;[...(S.acClose||[])].sort((a,b)=>a.id<b.id?-1:1).forEach(c=>{const h=sha256(prev+'|'+c.id+'|'+c.hs);if(c.prev!==prev||c.h!==h)badC++;prev=c.h;});return{bad,badC,n:(S.journal||[]).length};}
function acBalances(from,to){const B={};(S.journal||[]).filter(a=>(!from||a.f>=from)&&(!to||a.f<=to)).forEach(a=>a.l.forEach(l=>{const b=B[l.c]||(B[l.c]={d:0,h:0});b.d+=l.d;b.h+=l.h;}));return B;}
