let finTab='tablero';const FIN_TABS=[['tablero','Tablero'],['flujo','Flujo de fondos'],['cobrar','A cobrar'],['pagar','A pagar y compromisos'],['rentab','Rentabilidad'],['concil','Conciliación'],['pagos','Cobros digitales'],['ajustes','Ajustes']];
const finRO=()=>!can('finance_edit')&&!isAdm();
function finK(l,v,s,cls){return `<div class="card ux-k fin-k${cls?' '+cls:''}"><span>${esc(l)}</span><b>${v}</b>${s?`<small>${s}</small>`:''}</div>`;}
function finChart(F){const W=F.W,mx=Math.max(1,...W.map(w=>Math.max(w.inn,w.out)),...W.map(w=>Math.abs(w.bal)));const w0=720,h0=260,L=64,R=12,T=14,B=40,iw=w0-L-R,ih=h0-T-B,gw=iw/W.length,bw=Math.min(26,gw*.32);
 const mn=Math.min(0,...W.map(w=>w.bal)),Y=v=>T+ih-((v-mn)/(mx-mn||1))*ih;const z=Y(0);
 const bars=W.map((w,i)=>{const x=L+i*gw+gw/2;return `<rect x="${x-bw-1}" y="${Math.min(Y(w.inn),z)}" width="${bw}" height="${Math.abs(z-Y(w.inn))}" fill="var(--fin-in)"><title>Ingresos semana ${fDmy(w.from)}: ${money(w.inn)}</title></rect><rect x="${x+1}" y="${Math.min(Y(w.out),z)}" width="${bw}" height="${Math.abs(z-Y(w.out))}" fill="var(--fin-out)"><title>Egresos semana ${fDmy(w.from)}: ${money(w.out)}</title></rect><text x="${x}" y="${h0-B+16}" text-anchor="middle" font-size="11" fill="var(--mut)">${esc(fDmy(w.from).slice(0,5))}</text>`;}).join('');
 const pts=W.map((w,i)=>`${L+i*gw+gw/2},${Y(w.bal)}`).join(' ');
 const dots=W.map((w,i)=>`<circle cx="${L+i*gw+gw/2}" cy="${Y(w.bal)}" r="4" fill="${w.bal<finCfg().umbral?'var(--red)':'var(--ink)'}"><title>Saldo proyectado al ${fDmy(w.to)}: ${money(w.bal)}</title></circle>`).join('');
 return `<svg viewBox="0 0 ${w0} ${h0}" class="fin-chart" role="img" aria-label="Flujo de fondos proyectado por semana: barras de ingresos y egresos, línea de saldo"><line x1="${L}" x2="${w0-R}" y1="${z}" y2="${z}" stroke="var(--line)"/><text x="${L-6}" y="${z+4}" text-anchor="end" font-size="11" fill="var(--mut)">0</text><text x="${L-6}" y="${T+8}" text-anchor="end" font-size="11" fill="var(--mut)">${esc(chShort?chShort(mx):money(mx))}</text>${bars}<polyline points="${pts}" fill="none" stroke="var(--ink)" stroke-width="2"/>${dots}</svg>
 <p class="sm fin-leg"><span class="fin-sw" style="background:var(--fin-in)"></span>Ingresos esperados <span class="fin-sw" style="background:var(--fin-out)"></span>Egresos comprometidos <span class="fin-sw ln"></span>Saldo proyectado (punto rojo = por debajo del mínimo)</p>`;}
function finTable(F){return `<div class="tw"><table><thead><tr><th>Semana</th><th class="r">Ingresos</th><th class="r">Egresos</th><th class="r">Saldo proyectado</th><th>Detalle</th></tr></thead><tbody>${F.W.map(w=>`<tr${w.bal<finCfg().umbral?' class="fin-neg"':''}><td>${fDmy(w.from)} – ${fDmy(w.to)}</td><td class="r">${money(w.inn)}</td><td class="r">${money(w.out)}</td><td class="r"><b>${money(w.bal)}</b></td><td class="sm">${w.det.length?w.det.slice(0,4).map(d=>(d.kind==='in'?'+ ':'− ')+esc(d.txt)+' '+money(d.amt)).join('<br>')+(w.det.length>4?'<br>…y '+(w.det.length-4)+' más':''):'—'}</td></tr>`).join('')}</tbody></table></div>`;}
reg('finanzas','Finanzas','chart','finance',()=>{const c=finCfg();
 if(c.on)finInit();
 if(!c.on)return `<h1>Finanzas</h1><div class="card hr-off"><h2>Finanzas está apagado</h2><p>Tablero financiero con efectivo, bancos, lo que te deben y lo que debés; <b>flujo de fondos proyectado</b> semana a semana con alertas de baches de caja; rentabilidad real por operación; conciliación asistida del extracto bancario; tablero de cobros digitales y un copiloto que responde preguntas como «cuánta plata voy a tener en 15 días». Sólo lee lo que el sistema ya registra: no cambia ventas, caja ni compras.</p>${IS_CLIENT?'<p class="sm warnbox">Con la nube: antes de activarlo, el dueño pega en Supabase el script <b>27-finanzas-contable.sql</b> (sin ese script los datos nuevos quedan sólo en este equipo).</p>':''}${isAdm()?'<div class="row"><button class="btn gold" data-act="finToggle">Activar Finanzas</button></div>':'<p class="sm mut">Lo activa el administrador.</p>'}</div>`;
 const tabs=`<nav class="hr-tabs" role="tablist" aria-label="Secciones de Finanzas">${FIN_TABS.filter(([k])=>k!=='ajustes'||!finRO()).map(([k,t])=>`<button role="tab" class="${finTab===k?'on':''}" aria-selected="${finTab===k}" data-act="finTabGo" data-t="${k}">${t}</button>`).join('')}</nav>`;
 return `<div class="row"><h1 class="sp">Finanzas</h1>${finRO()?'<span class="tag">sólo lectura</span>':''}</div>${tabs}<div id="fin-body">${finBody()}</div>`;});
